+}
+
+.product-card p {
+  padding: 0.25rem 1rem 1rem;
+  color: #666;
+}
+
+.product-image {
+  width: 100%;
+  aspect-ratio: 4 / 3;
+}
+
+.product-detail {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 2rem;
+  align-items: start;
+}
+
+.product-hero {
+  width: 100%;
+  aspect-ratio: 1;
+  border-radius: 12px;
+}
+
+.product-info h1 {
