+}
+
+.product-description {
+  color: #666;
+  line-height: 1.6;
+}
+
+.back-link {
+  display: inline-block;
+  margin-bottom: 1.5rem;
+  color: #666;
+  text-decoration: none;
+}
+
+.skeleton-image {
+  background: #e5e5e5;
+  animation: pulse 1.5s ease-in-out infinite;
+}
+
+.skeleton-text {
+  height: 1rem;
+  background: #e5e5e5;
+  border-radius: 4px;
+  margin: 0.5rem 1rem;
+  animation: pulse 1.5s ease-in-out infinite;
+}
+
+.skeleton-text.short {
+  width: 60%;
+}
+
+.skeleton-text.large {
+  height: 2rem;
+  width: 70%;
+}
+
+@keyframes pulse {
+  0%,
+  100% {
+    opacity: 1;
+  }
+  50% {
+    opacity: 0.5;
+  }
+}
